-- STATE "flat" for MySQL Foundations lesson verification (generated by hand from the lessons;
-- see ~/projects/_kit_tools/mysql/SHELL_REFERENCE.md section 8). Idempotent.
-- The flat bookstore used in Module 3 (lessons 3.1-3.4) and at the start of 4.1:
-- books has a text author column; no authors/orders tables yet. Same rows as Lesson 3.1's reload block,
-- plus the canonical created_at values and example.com emails (see SHELL_REFERENCE conflicts C2, C3).
DROP DATABASE IF EXISTS bookstore;

CREATE DATABASE bookstore
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE bookstore;

CREATE TABLE books (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    title       VARCHAR(200) NOT NULL,
    author      VARCHAR(100) NOT NULL,
    price       DECIMAL(8, 2) NOT NULL,
    pages       INT,
    published   DATE,
    in_stock    BOOLEAN DEFAULT TRUE
);

CREATE TABLE customers (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    first_name  VARCHAR(50) NOT NULL,
    last_name   VARCHAR(50) NOT NULL,
    email       VARCHAR(100) NOT NULL UNIQUE,
    city        VARCHAR(50),
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE categories (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    name        VARCHAR(50) NOT NULL UNIQUE,
    description VARCHAR(255)
);

